private List<TopSortItemImpl<TaggedFunctionName>> inSpecificOrder(Set<TaggedFunctionName> fs) {
    TopSortItemImpl<TaggedFunctionName>[] pofuns = new OverloadSet.POTFN[fs.size()];
    int i = 0;
